test('non-OPEN 최초 소비는 원 OPEN credential·고정 transport·실제 decoder/ARM/STATE parser만 잇는다',async()=>{
 for(const phase of ['STREAM','ARM','STATE','CLOSE']as const){const f=await phaseHttpFixture(phase);try{const result=await f.client.consumeReceivePhase(f.input.window,f.input.challenge,f.input.request,f.input.body,f.source);assert.equal(f.state.signs,1);assert.equal(f.state.native,2);assert.equal(f.state.human,1,'fresh current는 원 owner source가 소비하며 Client의 중복조회0');assert.equal(JSON.stringify(result).includes('X'.repeat(43)),false);assert.equal(JSON.stringify(result).includes('A'.repeat(43)),false);if(phase==='STREAM'){assert.equal(result.kind,'DELIVERY');assert.deepEqual(result.metadata,f.delivery);}else assert.deepEqual(result,phase==='ARM'?f.arm:f.plainState(phase==='CLOSE'));}finally{f.client.disposeReceive();assert.equal(f.timers.size,0);}}
});

