 const f=await phaseHttpFixture('STATE');try{f.state.currentUntil=Date.parse(at)+3000;f.state.mode='HOLD_BODY';const pending=f.client.consumeReceivePhase(f.input.window,f.input.challenge,f.input.request,f.input.body,f.source);for(let n=0;n<100&&!f.state.releaseBody;n++)await Promise.resolve();assert.equal(typeof f.state.releaseBody,'function');assert.equal(f.state.deadline,Date.parse(at)+3000);assert.ok([...f.timers.values()].every((timer:any)=>timer.delay<=3000));f.state.now=Date.parse(at)+3000;for(const timer of [...f.timers.values()]as any[])timer.callback();await assert.rejects(pending,/NATIVE_RECEIVE_OUTCOME_UNKNOWN/);assert.equal(f.state.native,2);const count=f.state.native;f.state.releaseBody();await assert.rejects(f.client.readReceivePhaseResult(f.input.window,f.input.challenge,f.input.request,f.input.body));assert.equal(f.state.native,count);}finally{f.client.disposeReceive();assert.equal(f.timers.size,0);}
